 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Find a solid separator and the motif on its non-background side.
    sep_row = next((r for r in range(h) if all(x == 2 for x in grid[r])), None)
    sep_col = next((c for c in range(w) if all(grid[r][c] == 2 for r in range(h))), None)
    if sep_row is not None:
        bg = max(set(x for row in grid for x in row), key=lambda x: sum(v == x for row in grid for v in row))
        motif_rows = [r for r in range(h) if r != sep_row and any(v not in (bg, 2) for v in grid[r])]
        if motif_rows:
            # The guide stripe lies just outside the motif on the side away from separator.
            if max(motif_rows) < sep_row:
                target = min(motif_rows) - 1
            else:
                target = max(motif_rows) + 1
            if 0 <= target < h: out[target] = [8] * w
    elif sep_col is not None:
        bg = max(set(x for row in grid for x in row), key=lambda x: sum(v == x for row in grid for v in row))
        motif_cols = [c for c in range(w) if c != sep_col and any(grid[r][c] not in (bg, 2) for r in range(h))]
        if motif_cols:
            target = min(motif_cols) - 1 if max(motif_cols) < sep_col else max(motif_cols) + 1
            if 0 <= target < w:
                for r in range(h): out[r][target] = 8
    return out
